    [Xunit.Fact]
    public static void TestWhatEachPlatformEngineCannotSayIsNotInItsCeiling() {
        emon.Testport.AssertEq(Engines.PkEngineCaps(Engines.EngAppleVision()), 1056992, "Vision: quad angle lconf wlang walts");
        emon.Testport.AssertEq(Engines.PkEngineOen(Engines.EngAppleVision()), 3, "answers as engine 3");
        emon.Testport.AssertEq(Engines.PkEngineNeeds(Engines.EngAppleVision()), 0, "needs no pack");
        emon.Testport.AssertEq(Engines.PkEngineCaps(Engines.EngAppleVision()), VisionCaps(), "the bits, named");
        emon.Testport.AssertEq(Oil.OilNativeCheck(Engines.PkEngineCaps(Engines.EngAppleVision()), Oil.OcWconf()), 0, "no word confidence in the ceiling");
        emon.Testport.AssertEq(Engines.PkEngineCaps(Engines.EngWindowsMediaOcr()), 9216, "Windows: deskew wlang");
        emon.Testport.AssertEq(Engines.PkEngineNeeds(Engines.EngWindowsMediaOcr()), 0, "needs no pack");
        emon.Testport.AssertEq(Engines.PkEngineOen(Engines.EngWindowsMediaOcr()), 5, "answers as engine 5");
    }
